contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 maxChange, uint256 epochSize, uint8 changeTolerance, bool makeProposal) public {
        // Set up a successful-proposal configuration for the call.
        c.endConfiguration();
        c.setApprovedAsset(address(this), true, false, 0);
        c.makeProposal(address(this), address(this));

        bool reverted;
        try c.configureSecurityParameters(maxChange, epochSize, changeTolerance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 storedEpochSize,,) = c.proposalConfig();
        (,, uint8 storedTolerance) = c.security();

        assert(reverted == (changeTolerance >= 100));
    }

    receive() external payable {}
}

