contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 v1, uint256 v2, bool setActive) public {
        require(v1 > 0, "v1 must be nonzero");
        c.setEnforcement(setActive);

        bool active = c.enforceLimitsActive(address(this));
        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!active) {
            assert(!reverted);
        } else {
            uint256 lo = v1 > v2 ? v2 : v1;
            uint256 hi = v1 > v2 ? v1 : v2;
            bool violated = hi > lo && ((hi - lo) * 100) >= 5 * v1;
            assert(reverted == violated);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 v1, uint256 v2) public {
        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool wouldRevert;
        if (v1 > v2) {
            if (v2 == 0) {
                wouldRevert = v1 > 1;
            } else {
                wouldRevert = ((v1 - v2) * 100) >= 5 * v1;
            }
        } else {
            if (v1 == 0) {
                wouldRevert = v2 > 1;
            } else {
                wouldRevert = ((v2 - v1) * 100) >= 5 * v1;
            }
        }

        assert(reverted == wouldRevert);
    }
}

