            c.pendingFlashDecision(targetContract, address(this));

        bool expectedRevert =
            !(pAsset == asset && pAmount > 0 && pUnlockTime < block.timestamp);

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 qAmount, uint256 qUnlockTime, address qAsset, bool qBurnable) =
            c.pendingFlashDecision(targetContract, address(this));

        assert(
            (reverted == expectedRevert) &&
            (reverted || (qAmount == 0 && qAsset == address(0) && qUnlockTime == 0 && !qBurnable))
        );
    }

    receive() external payable {}
}

