contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address targetContract,
        address asset,
        bool assetBurnable,
        uint256 amount,
        uint256 unlockTime
    ) public payable {
        require(amount > 0, "amount must be positive");
        require(unlockTime < block.timestamp, "unlockTime must be in the past");

        // Create a pending flash decision for msg.sender on targetContract by calling
        // assertGovernanceApproved with this test contract as the sender. This requires
        // the flash governance asset to be configured and for this contract to have
        // enough tokens; otherwise the call reverts before setting the pending state.
        try c.assertGovernanceApproved(address(this), targetContract, false) {
            // Read the pending decision that was just created.
            (uint256 pendingAmount, uint256 pendingUnlock, address pendingAsset, ) =
                c.pendingFlashDecision(targetContract, address(this));

            // Only the configured asset should be used by assertGovernanceApproved.
            (, uint256 cfgAmount, uint256 cfgUnlockTime, address cfgAsset, bool cfgBurnable) =
                c.flashGovernanceConfig();
            require(pendingAsset == cfgAsset, "setup failed: wrong asset");
            require(pendingAmount == cfgAmount, "setup failed: wrong amount");

            // Try the withdrawal; it should succeed because amount > 0 and unlockTime is in the past.
            bool withdrew;
            try c.withdrawGovernanceAsset(targetContract, pendingAsset) {
                withdrew = true;
            } catch {
                withdrew = false;
            }

            // After a successful withdrawal, the pending entry must be deleted.
            (uint256 afterAmount, uint256 afterUnlock, address afterAsset, ) =
                c.pendingFlashDecision(targetContract, address(this));

            // General rule: if the withdrawal did not revert, then it must have
            // cleared the caller's pending decision for that target.
            assert(!withdrew || (afterAmount == 0 && afterUnlock == 0 && afterAsset == address(0)));
        } catch {
            // Setup could not be performed; the property is vacuously true.
            assert(true);
        }
    }

    receive() external payable {}
}

