    constructor(C _c) { c = _c; }

    function run(address[] calldata governables, bool[] calldata isGoverned) public {
        c.endConfiguration();
        c.setDAO(address(this));

        bool reverted;
        try c.setGoverned(governables, isGoverned) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool allMatch = true;
        for (uint256 i = 0; i < governables.length; i++) {
            if (c.governed(governables[i]) != isGoverned[i]) {
                allMatch = false;
            }
        }

        bool lengthMismatch = governables.length != isGoverned.length;

        assert(reverted || !lengthMismatch && allMatch);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address sender,
        address target,
        bool emergency,
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool assetBurnable
    ) public payable {
        require(asset != address(this), "test asset must not be test contract");
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        (address curAsset, uint256 curAmount, uint256 curUnlockTime, bool curBurnable) = c.flashGovernanceConfig();
        require(curAsset == asset && curAmount == amount && curUnlockTime == unlockTime && curBurnable == assetBurnable, "config not set");

        (, uint256 lastAct, uint256 epochSize, ) = c.security();

        (uint256 unlockedBefore, address pendingAssetBefore, uint256 pendingAmountBefore, uint256 pendingUnlockTimeBefore) = c.pendingFlashDecision(target, sender);

        bool transferOk;
        try IERC20(asset).transferFrom(sender, address(c), amount) {
            transferOk = true;
        } catch {
            transferOk = false;
        }

        bool reverted;
        try c.assertGovernanceApproved(sender, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint256 pendingUnlockAfter, , , ) = c.pendingFlashDecision(target, sender);

        bool epochBlocked = !emergency && epochSize > 0 && block.timestamp - lastAct <= epochSize;
        bool pendingBlocked = pendingUnlockTimeBefore > 0 && pendingUnlockTimeBefore >= block.timestamp;
        bool expectedRevert = !transferOk || pendingBlocked || epochBlocked;

        assert(reverted == expectedRevert);
    }

    receive() external payable {}
}

