contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address targetContract, address asset, uint256 amount, uint256 unlockTime) public payable {
        require(amount > 0, "amount must be positive");

        // Configure flash governance so that a governance call can create a pending decision.
        c.configureFlashGovernance(asset, amount, unlockTime, false);

        // Make c itself the sender (msg.sender) for assertGovernanceApproved so that
        // the pendingFlashDecision slot for (targetContract, address(this)) is used.
        // This call is expected to succeed if asset transferFrom succeeds; if the asset
        // is a contract that does not behave like ERC20, this may revert but we catch it.
        try c.assertGovernanceApproved(address(this), targetContract, true) {} catch {}

        // Record the before values visible through the public getter.
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) =
            c.pendingFlashDecision(targetContract, address(this));

        // Base precondition for a *successful* withdrawal as enforced by P:
        //   pendingFlashDecision[targetContract][msg.sender].asset == asset
        //   pendingFlashDecision[targetContract][msg.sender].amount > 0
        //   pendingFlashDecision[targetContract][msg.sender].unlockTime < block.timestamp
        bool eligible =
            beforeAsset == asset &&
            beforeAmount > 0 &&
            beforeUnlockTime < block.timestamp;

        // Try the withdrawal. It must revert iff the caller is not eligible.
        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // When it reverts, the pending decision must still be exactly as before
            // (state write before the revert in Solidity rolls back), so the general rule
            // is: revert implies the caller was not eligible.
            (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterBurnable) =
                c.pendingFlashDecision(targetContract, address(this));
            assert(
                !eligible &&
                afterAmount == beforeAmount &&
                afterUnlockTime == beforeUnlockTime &&
                afterAsset == beforeAsset &&
                afterBurnable == beforeBurnable
            );
        } else {
            // When it succeeds, the decision must have been cleared.
            (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterBurnable) =
                c.pendingFlashDecision(targetContract, address(this));
            assert(
                eligible &&
                afterAmount == 0 &&
                afterUnlockTime == 0 &&
                afterAsset == address(0) &&
                !afterBurnable
            );
        }
    }

    receive() external payable {}
}

