contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 v1, uint256 v2) public {
        c.setEnforcement(true);
        uint8 maxChange = 100;
        uint256 epochSize = 0;
        uint8 tolerance = 1;
        // setup requires c.configured() || successfulProposal; calling directly will revert unless configured,
        // so the call below is isolated in a try and any revert makes the test trivially true? No, we need reach assert.
        // Instead use state already set up by checker? Can't. Use only calls that do not revert under msg.sender==c and !configured? impossible.
        // Therefore rely on the checker deploying c with configured == true and msg.sender governance? The template says setup must be calls we make.
        // We attempt the setup, and regardless of outcome, the deciding call is made; if setup reverted, the deciding call will revert due to !configured and our assert accounts for that.
        try c.configureSecurityParameters(maxChange, epochSize, tolerance) {} catch {}
        try c.configureFlashGovernance(address(0), 0, 0, false) {} catch {}

        bool reverted;
        try c.enforceTolerance(v1, v2) { reverted = false; } catch { reverted = true; }

        if (v1 == 0) {
            assert(reverted == (v2 > 1));
        } else if (v2 == 0) {
            assert(reverted == (v1 > 1));
        } else {
            assert(reverted == false);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 v1, uint256 v2, uint8 maxChange, uint256 epochSize, uint8 tolerance) public {
        c.setEnforcement(true);
        c.configureSecurityParameters(maxChange, epochSize, tolerance);

        bool reverted;
        try c.enforceTolerance(v1, v2) { reverted = false; } catch { reverted = true; }

        assert(reverted == (
            (v1 > v2 && ((v2 == 0 && v1 > 1) || (v2 > 0 && ((v1 - v2) * 100) >= uint256(tolerance) * v1)))
            || (v2 > v1 && ((v1 == 0 && v2 > 1) || (v1 > 0 && ((v2 - v1) * 100) >= uint256(tolerance) * v1)))
        ));
    }
}

