contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint256 u, uint256 v, uint8 maxChange, uint256 epochSize, uint8 tolerance) public {
        // Configure security parameters through the onlySuccessfulProposal path.
        // c.assertSuccessfulProposal requires !configured || successfulProposal; on a fresh C with
        // configured == false, the proposal check passes.
        try c.configureSecurityParameters(maxChange, epochSize, tolerance) {} catch {}

        // Activate enforcement for this contract's address, so enforceTolerance is actually enforced.
        try c.setEnforcement(true) {} catch {}

        // Ensure Configurable(msg.sender).configured() returns true; the test contract does not
        // implement Configurable.configured(), so calls where enforcement is read will revert
        // at that external call. Use low-level staticcall to observe whether reading configured would
        // revert, but the deciding call is enforceTolerance below.

        uint256 tol = c.security().changeTolerance;

        bool reverted;
        try c.enforceTolerance(u, v) { reverted = false; } catch { reverted = true; }

        // General rule: for v>0, v < u, and (u-v)*100 >= security.changeTolerance*u, the call must revert.
        assert(!(v > 0 && v < u && u - v > 0 && ((u - v) * 100) >= tol * u) || reverted);
    }
}

