        c.setGoverned(governables, isGoverned);

        // After the call, each key must equal the provided value.
        for (uint256 i = 0; i < governables.length; i++) {
            assert(c.governed(governables[i]) == isGoverned[i]);
        }
    }

    receive() external payable {}
}

