    function run(
        address asset,
        uint256 amount,
        uint256 unlockTime,
        bool burnable,
        address sender,
        address target,
        bool emergency
    ) public {
        // Initialization: configure flash governance for the asset, amount, unlockTime, burnable.
        c.configureFlashGovernance(asset, amount, unlockTime, burnable);

        // Read the configured flashGovernanceConfig (public getter returns asset, amount, unlockTime, assetBurnable)
        (address cfgAsset, uint256 cfgAmount, uint256 cfgUnlockTime, bool cfgBurnable) = c.flashGovernanceConfig();

