        try IERC20(asset).transferFrom(sender, address(c), cfgAmount) returns (bool success) {
            transferFromSucceeded = success;
        } catch {
            transferFromSucceeded = false;
        }

        uint256 unlock = cfgUnlockTime;
        bool unlockPastOrEqual = (block.timestamp >= unlock); // since condition uses < block.timestamp for pending decision

        bool epochCondition = emergency || (block.timestamp > c.security().lastFlashGovernanceAct + c.security().epochSize());

        bool expectedSuccess = senderAllowed && transferFromSucceeded && unlockPastOrEqual && epochCondition;
        bool reverted;
        try c.assertGovernanceApproved(sender, target, emergency) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == !expectedSuccess);
    }

    receive() external payable {}
}

