contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address targetContract, address asset, uint256 unlockTime, uint256 amount, bool assetBurnable) public {
        // Configure the flash governance config so that a decision can be registered.
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // Register a pending decision from this test contract as caller, targeting targetContract.
        c.assertGovernanceApproved(address(this), targetContract, true);

        // Read the pending entry that was just created.
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, ) = c.pendingFlashDecision(targetContract, address(this));

        bool beforeHasStoredAsset = beforeAsset == asset;
        bool beforePositive = beforeAmount > 0;

        // Move past the stored unlock time so the first withdrawal is eligible.
        // Use the stored value read back (which may differ from the parameter due to config).
        // block.timestamp is already advanced enough because the environment timestamp is nonzero;
        // we rely on the stored value being a function of the configured value.

        // First deciding call: withdraw the governance asset.
        bool firstReverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Second deciding call: after a successful withdrawal the entry must have been deleted,
        // so this identical call must now revert.
        bool secondReverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule: the first withdrawal succeeds iff a matching pending entry existed with
        // positive amount and expired unlock time. If it succeeded, the entry is deleted, so the
        // second call must revert. If it failed, the second must also fail (no new entry is created).
        bool rule =
            (!firstReverted) == (beforeHasStoredAsset && beforePositive && beforeUnlockTime < block.timestamp)
            && (firstReverted || secondReverted);
        assert(rule);
    }
}

