contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 v1, uint256 v2) public view {
        // enforceTolerance is a view function: calling it is the deciding call.
        // We only read c's public surface: security() and enforceLimitsActive(address(this)).
        (, , uint8 tolerance) = c.security();
        bool limited = c.enforceLimitsActive(address(this));

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The early-return guard fires when the caller is not both limited and configured.
        // In that case the function must always complete without reverting.
        // When the caller IS limited and configured, the tolerance check applies:
        //   if v1 > v2: if v2 == 0 then require(v1 <= 1); else require((v1-v2)*100 < tol*v1)
        //   else:       if v1 == 0 then require(v2 <= 1); else require((v2-v1)*100 < tol*v1)
        bool mustRevert;
        if (!limited || !Configurable(address(this)).configured()) {
            mustRevert = false;
        } else if (v1 > v2) {
            if (v2 == 0) {
                mustRevert = v1 > 1;
            } else {
                mustRevert = v1 <= 1 || ((v1 - v2) * 100 >= uint256(tolerance) * v1);
            }
        } else {
            if (v1 == 0) {
                mustRevert = v2 > 1;
            } else {
                mustRevert = v1 <= 1 || ((v2 - v1) * 100 >= uint256(tolerance) * v1);
            }
        }

        assert(reverted == mustRevert);
    }

    function configured() public view returns (bool) {
        return true;
    }

    receive() external payable {}
}

