        } else {
            // If the transfer succeeds, the contract's asset balance increases by amount.
            // We cannot know the exact prior balance without a view call, but the call's
            // success is observable by the balance delta on the contract.
            transferOk = true;
        }

        bool gateOk = emergency || (block.timestamp - lastFlashGovernanceAct > epochSize);
        bool enabled = (msg.sender == dao || governed);

        assert(reverted != (enabled && transferOk && gateOk && unlockTimeOk));

        // We cannot observe unlockTimeOk before the call, so the rule is only stated
        // when the pending window is closed, which is a parameter-free observable.
    }
}

