contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address targetContract, address asset, uint256 amount, uint256 unlockTime) public {
        // Read the stored pending decision before the deciding call.
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) = c.pendingFlashDecision(targetContract, address(this));

        bool exists = beforeAsset == asset && beforeAmount > 0 && beforeUnlockTime < block.timestamp;
        bool shouldSucceed = exists;

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, the pending decision should be deleted iff the call succeeded.
        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterBurnable) = c.pendingFlashDecision(targetContract, address(this));
        bool afterCleared = afterAmount == 0 && afterUnlockTime == 0 && afterAsset == address(0) && afterBurnable == false;

        // If the call succeeded, the stored entry must have been cleared; if it reverted,
        // the stored entry must have been left untouched.
        assert((!reverted) == shouldSucceed && (!reverted ? afterCleared : (afterAmount == beforeAmount && afterUnlockTime == beforeUnlockTime && afterAsset == beforeAsset && afterBurnable == beforeBurnable)));
    }
}

