        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) =
            c.pendingFlashDecision(targetContract, address(this));

        // The call is meant to succeed iff there is a matching pending decision for the caller
        // with the requested asset, a positive amount, and an already-past unlock time.
        bool shouldSucceed =
            beforeAsset == asset && beforeAmount > 0 && beforeUnlockTime < block.timestamp;

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
