        // Nothing in pendingFlashDecision can be touched on revert; it must be cleared on success.
        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterBurnable) =
            c.pendingFlashDecision(targetContract, address(this));

        bool afterCleared =
            afterAmount == 0 && afterUnlockTime == 0 && afterAsset == address(0) && afterBurnable == false;

        bool afterUnchanged =
            afterAmount == beforeAmount &&
            afterUnlockTime == beforeUnlockTime &&
            afterAsset == beforeAsset &&
            afterBurnable == beforeBurnable;

        assert(
            (!reverted == shouldSucceed) &&
            (!reverted ? afterCleared : afterUnchanged)
        );
    }
}

