contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address targetContract, address asset, uint256 amount, uint256 unlockTime) public {
        // A successful-path template for pendingFlashDecision(target, msg.sender): asset, amount, unlock time.
        // configureFlashGovernance sets exactly these fields, so we first try to arm the pending entry.
        uint256 nowTs = block.timestamp;
        uint256 armedUnlock = nowTs == 0 ? 0 : nowTs - 1; // an unlock time guaranteed to be already in the past

        // Governance-side configuration that the contract exposes publicly.
        c.configureFlashGovernance(asset, amount, armedUnlock, false);

        // Try to create the pending decision for (targetContract, this contract).
        // It can fail (transferFrom of asset may fail), so capture the outcome; this is setup, not the rule call.
        bool setupReverted;
        try c.assertGovernanceApproved(address(this), targetContract, true) {
            setupReverted = false;
        } catch {
            setupReverted = true;
        }

        // Read the pending entry for (targetContract, msg.sender) before the deciding call.
        (uint256 beforeAmount, uint256 beforeUnlockTime, address beforeAsset, bool beforeBurnable) =
            c.pendingFlashDecision(targetContract, address(this));

        // The pending entry is good raw material for the call iff it matches the requested asset,
        // has a positive amount, and its unlock time is already in the past.
        bool entryPresent =
            beforeAsset == asset && beforeAmount > 0 && beforeUnlockTime < block.timestamp;

        // If setup did not actually arm the entry, the call must revert. If it did, success is intended.
        bool shouldSucceed = !setupReverted && entryPresent;

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the pending entry again: success must clear it, revert must leave it untouched.
        (uint256 afterAmount, uint256 afterUnlockTime, address afterAsset, bool afterBurnable) =
            c.pendingFlashDecision(targetContract, address(this));

        bool afterCleared =
            afterAmount == 0 && afterUnlockTime == 0 && afterAsset == address(0) && afterBurnable == false;

        bool afterUnchanged =
            afterAmount == beforeAmount &&
            afterUnlockTime == beforeUnlockTime &&
            afterAsset == beforeAsset &&
            afterBurnable == beforeBurnable;

        assert(
            (reverted == !shouldSucceed) &&
            (reverted ? afterUnchanged : afterCleared)
        );
    }
}

