contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 v1, uint256 v2) public payable {
        require(v1 <= type(uint256).max / 100);
        require(v2 <= type(uint256).max / 100);

        bool active = false;
        try c.enforceLimitsActive(address(this)) returns (bool a) {
            active = a;
        } catch {}

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (, , , , uint8 changeTolerance) = c.security();

        bool expectedRevert;
        if (!active) {
            expectedRevert = false;
        } else {
            if (v1 > v2) {
                if (v2 == 0) {
                    expectedRevert = v1 > 1;
                } else {
                    expectedRevert = !((v1 - v2) * 100 < uint256(changeTolerance) * v1);
                }
            } else {
                if (v1 == 0) {
                    expectedRevert = v2 > 1;
                } else {
                    expectedRevert = !((v2 - v1) * 100 < uint256(changeTolerance) * v1);
                }
            }
        }

        assert(reverted == expectedRevert);
    }

    receive() external payable {}
}

